// Removing an arbitrary node from a doubly linked list is O(1)
// because both neighbors are reachable directly from the node.
Node* prevNode = node->prev;
Node* nextNode = node->next;
prevNode->next = nextNode;
nextNode->prev = prevNode;
// node is now fully unlinked, no traversal was needed

class LRUCache {
    struct Node {
        int key, value;
        Node* prev;
        Node* next;
        Node(int k, int v) : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    int capacity;
    unordered_map<int, Node*> map;   // key -> node pointer, O(1) lookup
    Node* head;                      // sentinel, head->next is the MRU real node
    Node* tail;                      // sentinel, tail->prev is the LRU real node

    // Unlink an existing node from wherever it currently sits. O(1).
    void removeNode(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    // Insert a node right after the head sentinel, making it MRU. O(1).
    void insertAtFront(Node* node) {
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }

public:
    LRUCache(int cap) : capacity(cap) {
        head = new Node(-1, -1);
        tail = new Node(-1, -1);
        head->next = tail;
        tail->prev = head;
    }

    int get(int key) {
        if (map.find(key) == map.end()) {
            return -1;                      // not found
        }
        Node* node = map[key];
        removeNode(node);
        insertAtFront(node);                // mark as most recently used
        return node->value;
    }

    void put(int key, int value) {
        if (map.find(key) != map.end()) {
            Node* node = map[key];
            node->value = value;            // update existing value
            removeNode(node);
            insertAtFront(node);            // mark as most recently used
            return;
        }

        if ((int)map.size() == capacity) {
            Node* lru = tail->prev;         // node right before tail sentinel
            removeNode(lru);
            map.erase(lru->key);            // critical: also erase from the map
            delete lru;
        }

        Node* fresh = new Node(key, value);
        insertAtFront(fresh);
        map[key] = fresh;
    }

    ~LRUCache() {
        Node* cur = head;
        while (cur) {
            Node* next = cur->next;
            delete cur;
            cur = next;
        }
    }
};
